theorem exists_adjacent_eq_of_not_strict {K : Complex ι} {n : ℕ}
    (v : OrderedSimplex K (n + 1)) (hv : ¬ StrictMono v.val) :
    ∃ i : Fin (n + 1), v.val i.castSucc = v.val i.succ

